@RunWith(MockitoJUnitRunner.class)
public class AbstractScopeBuilder_visit_TriageGen0Test {

    @Mock
    private NodeTraversal t;
    @Mock
    private Node n;
    @Mock
    private Node parent;
    @Mock
    private Node firstChild;
    @Mock
    private Node nextChild;
    @Mock
    private JSDocInfo jsDocInfo;

    private TypedScopeCreator.AbstractScopeBuilder scopeBuilder;

    @Before
    public void setUp() {
        // Since AbstractScopeBuilder is likely abstract or part of a complex hierarchy, 
        // we spy on a concrete implementation or a mocked version if possible.
        // For the purpose of this test, we assume we are testing a subclass or a mockable version.
        scopeBuilder = spy(new TypedScopeCreator.AbstractScopeBuilder() {
            // Stubbing abstract methods if any exist in the real class
            @Override
            protected void attachLiteralTypes(NodeTraversal t, Node n) {}
            @Override
            protected void checkForClassDefiningCalls(NodeTraversal t, Node n, Node parent) {}
            @Override
            protected void checkForCallingConventionDefiningCalls(Node n, java.util.Map<String, String> delegate) {}
            @Override
            protected void defineFunctionLiteral(Node n, Node parent) {}
            @Override
            protected void maybeDeclareQualifiedName(NodeTraversal t, JSDocInfo jsDoc, Node nameNode, Node assignNode, Node next) {}
            @Override
            protected void defineCatch(Node n, Node parent) {}
            @Override
            protected void defineVar(Node n, Node parent) {}
        });

        when(t.getInputId()).thenReturn("testId");
    }

    @Test
    public void testVisit_Call() {
        when(n.getType()).thenReturn(Token.CALL);

        scopeBuilder.visit(t, n, parent);

        verify(scopeBuilder).checkForClassDefiningCalls(eq(t), eq(n), eq(parent));
        verify(scopeBuilder).checkForCallingConventionDefiningCalls(eq(n), any());
    }

    @Test
    public void testVisit_Function_NonExtern() {
        when(n.getType()).thenReturn(Token.FUNCTION);
        Node input = mock(Node.class);
        when(input.isExtern()).thenReturn(false);
        when(t.getInput()).thenReturn(input);

        // Mock NodeUtil.isHoistedFunctionDeclaration behavior via a mockable context if possible, 
        // here we assume it returns false for coverage.
        // Since NodeUtil is static, we rely on the actual implementation or assume it's not hoisted.

        scopeBuilder.visit(t, n, parent);

        verify(scopeBuilder).defineFunctionLiteral(eq(n), eq(parent));
    }

    @Test
    public void testVisit_Function_Extern() {
        when(n.getType()).thenReturn(Token.FUNCTION);
        Node input = mock(Node.class);
        when(input.isExtern()).thenReturn(true);
        when(t.getInput()).thenReturn(input);

        scopeBuilder.visit(t, n, parent);

        verify(scopeBuilder, never()).defineFunctionLiteral(any(), any());
    }

    @Test
    public void testVisit_Function_NullInput() {
        when(n.getType()).thenReturn(Token.FUNCTION);
        when(t.getInput()).thenReturn(null);

        scopeBuilder.visit(t, n, parent);
        // Should not crash and proceeds to defineFunctionLiteral if not hoisted
        verify(scopeBuilder).defineFunctionLiteral(eq(n), eq(parent));
    }

    @Test
    public void testVisit_Assign_QualifiedName() {
        when(n.getType()).thenReturn(Token.ASSIGN);
        when(n.getFirstChild()).thenReturn(firstChild);
        when(firstChild.isGetProp()).thenReturn(true);
        when(firstChild.isQualifiedName()).thenReturn(true);
        when(firstChild.getNext()).thenReturn(nextChild);
        when(n.getJSDocInfo()).thenReturn(jsDocInfo);

        scopeBuilder.visit(t, n, parent);

        verify(scopeBuilder).maybeDeclareQualifiedName(t, jsDocInfo, firstChild, n, nextChild);
    }

    @Test
    public void testVisit_Assign_NotQualified() {
        when(n.getType()).thenReturn(Token.ASSIGN);
        when(n.getFirstChild()).thenReturn(firstChild);
        when(firstChild.isGetProp()).thenReturn(true);
        when(firstChild.isQualifiedName()).thenReturn(false);

        scopeBuilder.visit(t, n, parent);

        verify(scopeBuilder, never()).maybeDeclareQualifiedName(any(), any(), any(), any(), any());
    }

    @Test
    public void testVisit_Catch() {
        when(n.getType()).thenReturn(Token.CATCH);

        scopeBuilder.visit(t, n, parent);

        verify(scopeBuilder).defineCatch(n, parent);
    }

    @Test
    public void testVisit_Var() {
        when(n.getType()).thenReturn(Token.VAR);

        scopeBuilder.visit(t, n, parent);

        verify(scopeBuilder).defineVar(n, parent);
    }

    @Test
    public void testVisit_GetProp_QualifiedAndExprResult() {
        when(n.getType()).thenReturn(Token.GETPROP);
        when(n.isQualifiedName()).thenReturn(true);
        when(parent.isExprResult()).thenReturn(true);
        when(n.getJSDocInfo()).thenReturn(jsDocInfo);

        scopeBuilder.visit(t, n, parent);

        verify(scopeBuilder).maybeDeclareQualifiedName(t, jsDocInfo, n, parent, null);
    }

    @Test
    public void testVisit_GetProp_NotQualified() {
        when(n.getType()).thenReturn(Token.GETPROP);
        when(n.isQualifiedName()).thenReturn(false);
        when(parent.isExprResult()).thenReturn(true);

        scopeBuilder.visit(t, n, parent);

        verify(scopeBuilder, never()).maybeDeclareQualifiedName(any(), any(), any(), any(), any());
    }

    @Test
    public void testVisit_GetProp_NotExprResult() {
        when(n.getType()).thenReturn(Token.GETPROP);
        when(n.isQualifiedName()).thenReturn(true);
        when(parent.isExprResult()).thenReturn(false);

        scopeBuilder.visit(t, n, parent);

        verify(scopeBuilder, never()).maybeDeclareQualifiedName(any(), any(), any(), any(), any());
    }
}
